const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const safe = (fn, fallback = null) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

// WF-10 | Stage 2 - Data Processing: gom cấu hình + đọc header/body của webhook.
// =====================================================================================
//  WF-10 | CẤU HÌNH TẬP TRUNG (chỉ cần sửa ở khối này)
// =====================================================================================
// Model đọc ảnh: lấy từ biến môi trường GEMINI_MODEL của n8n (docker-compose đã truyền sẵn, cùng model WF-01/02 đang dùng).
// Nếu đọc không được biến môi trường thì dùng giá trị dự phòng bên dưới.
// Nếu thấy chữ đọc sai nhiều, đổi sang model mạnh hơn (ví dụ gemini-2.5-flash) bằng cách sửa FALLBACK_MODEL
// và đặt GEMINI_MODEL trống, hoặc sửa thẳng biến MODEL.
const FALLBACK_MODEL = 'gemini-2.5-flash';
const MODEL = s(safe(() => $env.GEMINI_MODEL, ''), 80) || FALLBACK_MODEL;
const LIMITS = {
  maxBytes: 8 * 1024 * 1024,   // ảnh/PDF tối đa 8 MB (Gemini nhận inline tối đa ~20 MB sau khi mã hóa base64)
  minConfidence: 0.6,          // dưới mức này (AI tự chấm 0..1) => đánh dấu needs_review, KHÔNG tự tạo lead
  maxTextChars: 200000,        // lưu tối đa 200 nghìn ký tự chữ gốc vào documents.extracted_text
};
const DEFAULT_ORG_ID = '11111111-1111-4111-8111-111111111111';
// =====================================================================================

const hCorr = s(($json.headers || {})['x-correlation-id'], 60);
return {
  json: {
    body: $json.body || {},
    config: { vision: { provider: 'gemini', model: MODEL }, limits: LIMITS, defaultOrgId: DEFAULT_ORG_ID },
    correlationId: UUID_RE.test(hCorr) ? hCorr.toLowerCase() : newUuid(),
  },
  binary: $input.item.binary,
};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const safe = (fn, fallback = null) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

// WF-10 | Stage 3 - Validation của file upload (tên trường bắt buộc: "file").
const c = $('02 Config and Mode').item.json;
const L = c.config.limits;
const b = c.body || {};
const f = ($input.item.binary || {}).file;
const DOC_TYPES = ['auto', 'business_card', 'contract'];
const errors = [];
let httpCode = 422;

// Trình duyệt/curl hay gửi tên UTF-8 bị giải mã nhầm latin1 ("Ä\u0090á»\u0095i" thay cho "Đổi"): sửa lại khi nhìn là biết sai.
const fixName = (n) => {
  const x = s(n, 255);
  try { const u = Buffer.from(x, 'latin1').toString('utf8'); if (u !== x && !/\uFFFD/.test(u) && /[\u00C2-\u00C5\u00E1]/.test(x)) return u; } catch (e) {}
  return x;
};
// Nhận dạng loại file bằng "chữ ký" đầu file, không tin đuôi file hay Content-Type do người gửi khai.
const detectMime = (buf) => {
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'image/jpeg';
  if (buf.length >= 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) return 'image/png';
  if (buf.length >= 12 && buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
  if (buf.subarray(0, 1024).toString('latin1').indexOf('%PDF-') !== -1) return 'application/pdf';
  return '';
};
// Dấu vân tay nội dung (2 vòng băm 32-bit + độ dài) để phát hiện cùng một file gửi lại.
const fingerprint = (buf) => {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < buf.length; i++) { const ch = buf[i]; h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0') + '-' + buf.length.toString(16);
};

let fileName = '', sizeBytes = 0, mimeType = '', fileHash = '', b64 = '';
if (!f) {
  errors.push({ field: 'file', code: 'FILE_REQUIRED', message: 'Cần đính kèm ảnh/PDF ở trường có tên "file" (multipart/form-data).' });
} else {
  fileName = fixName(f.fileName || 'upload');
  const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'file');
  sizeBytes = buf.length;
  mimeType = detectMime(buf);
  if (sizeBytes === 0) errors.push({ field: 'file', code: 'EMPTY_FILE', message: 'File rỗng.' });
  else if (!mimeType) errors.push({ field: 'file', code: 'UNSUPPORTED_FILE_TYPE', message: 'Chỉ nhận ảnh JPG, PNG, WEBP hoặc file PDF.' });
  else if (sizeBytes > L.maxBytes) { errors.push({ field: 'file', code: 'FILE_TOO_LARGE', message: 'File vượt quá ' + Math.round(L.maxBytes / 1048576) + ' MB.' }); httpCode = 413; }
  else { fileHash = fingerprint(buf); b64 = buf.toString('base64'); }
}

const orgRaw = s(b.organizationId, 60);
const organizationId = UUID_RE.test(orgRaw) ? orgRaw.toLowerCase() : c.config.defaultOrgId;
if (orgRaw && !UUID_RE.test(orgRaw)) errors.push({ field: 'organizationId', code: 'INVALID_ORGANIZATION', message: 'organizationId phải là UUID.' });

const dtRaw = s(b.docType, 30).toLowerCase();
if (dtRaw && !DOC_TYPES.includes(dtRaw)) errors.push({ field: 'docType', code: 'INVALID_DOC_TYPE', message: 'docType phải là một trong: ' + DOC_TYPES.join(', ') + '.' });
const flag = (v, def) => { const t = s(v, 10).toLowerCase(); if (['true', '1', 'yes'].includes(t)) return true; if (['false', '0', 'no'].includes(t)) return false; return def; };

const upload = {
  fileName: fileName.slice(0, 255), sizeBytes, mimeType, fileHash,
  docType: DOC_TYPES.includes(dtRaw) ? dtRaw : 'auto',
  createLead: flag(b.createLead, true),
  replace: flag(b.replace, false),
};
return {
  json: {
    valid: errors.length === 0, errors, httpCode, upload, organizationId, correlationId: c.correlationId,
    b64: errors.length === 0 ? b64 : '',
    runInput: { fileName: upload.fileName, sizeBytes, mimeType, fileHash, docType: upload.docType, createLead: upload.createLead, replace: upload.replace },
  },
};

