parameters.jsCode:
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const safe = (fn, fallback = null) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

// WF-10 | Stage 6 - AI/LLM: dựng yêu cầu gửi Gemini (prompt + khuôn JSON bắt buộc trả về).
const c = $('02 Config and Mode').first().json;
const up = $('03 Validate Upload').first().json.upload;
const model = c.config.vision.model;

const T = (extra) => Object.assign({ type: 'STRING', nullable: true }, extra || {});
const SCHEMA = {
  type: 'OBJECT',
  properties: {
    documentType: { type: 'STRING', enum: ['business_card', 'contract', 'other', 'unreadable'] },
    language: T(),
    confidence: { type: 'NUMBER' },
    rawText: { type: 'STRING' },
    businessCard: {
      type: 'OBJECT', nullable: true,
      properties: { fullName: T(), jobTitle: T(), companyName: T(), email: T(), phone: T(), phoneOther: T(), website: T(), address: T() },
    },
    contract: {
      type: 'OBJECT', nullable: true,
      properties: {
        title: T(), contractNumber: T(), signedDate: T(), effectiveDate: T(), expiryDate: T(),
        parties: { type: 'ARRAY', items: { type: 'OBJECT', properties: { name: T(), role: T(), representative: T() } } },
        totalValue: { type: 'NUMBER', nullable: true }, currency: T(), paymentTerms: T(), renewalTerms: T(), summary: T(),
      },
    },
  },
  required: ['documentType', 'confidence', 'rawText'],
};

const hint = up.docType === 'business_card' ? 'The sender says this is a BUSINESS CARD.'
  : up.docType === 'contract' ? 'The sender says this is a CONTRACT / AGREEMENT.'
  : 'The sender did not say what kind of document this is; decide yourself.';

const prompt = [
  'You are an OCR and information-extraction engine for a Vietnamese sales team. The attached file is a photo or scan.',
  hint,
  'Tasks:',
  '1. Set documentType: "business_card", "contract", "other" (a readable document of another kind) or "unreadable" (blank, too blurry, or no text).',
  '2. Put ALL visible text in rawText, in natural reading order, keeping Vietnamese diacritics exactly. Never translate.',
  '3. If business_card, fill businessCard. If contract, fill contract. Leave the other object null.',
  '4. Rules: copy values exactly as printed; NEVER guess or invent a value that is not visible (use null instead).',
  '   - Dates as YYYY-MM-DD (Vietnamese dates are day/month/year, e.g. "ngày 15 tháng 03 năm 2026" -> 2026-03-15).',
  '   - totalValue is a plain number without separators (e.g. 120.000.000 -> 120000000); currency is a code such as VND or USD.',
  '   - phone = the main mobile/contact number; phoneOther = any other numbers joined by ", ".',
  '   - contract.parties lists every party (e.g. Bên A / Bên B) with name, role and representative; summary is 1-2 sentences in Vietnamese.',
  '5. confidence is your honest 0..1 estimate of how reliably you read the file (blurry, cut-off or handwritten => lower).',
  'Return ONLY a JSON object that matches the response schema.',
].join('\n');

return {
  json: {
    url: 'https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(model) + ':generateContent',
    prompt,
    generationConfig: { temperature: 0, maxOutputTokens: 16384, responseMimeType: 'application/json', responseSchema: SCHEMA },
  },
};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const s = (v, max = 500) => (v === undefined || v === null ? '' : String(v).trim().slice(0, max));
const safe = (fn, fallback = null) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };
const newUuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

// WF-10 | Stage 3/6/7 - đọc câu trả lời của Gemini, kiểm tra, chuẩn hóa, quyết định có tạo lead hay cần người xem lại.
const c = $('02 Config and Mode').first().json;
const up = $('03 Validate Upload').first().json.upload;
const L = c.config.limits;
const resp = $json || {};

const errors = [];
let httpCode = 422, logStatus = 'rejected';
const fail = (code, message, http, status) => { errors.push({ code, message }); if (http) httpCode = http; if (status) logStatus = status; };

const cand = (resp.candidates || [])[0] || {};
const finishReason = s(cand.finishReason, 40);
const text = ((cand.content && cand.content.parts) || []).map((p) => (p && p.text) || '').join('').trim();
const blockReason = s(safe(() => resp.promptFeedback.blockReason, ''), 60);
const provider = { name: 'gemini', model: c.config.vision.model, finishReason, usage: resp.usageMetadata || null };

let ai = null;
if (blockReason) fail('BLOCKED_BY_PROVIDER', 'Nhà cung cấp AI từ chối xử lý file này (' + blockReason + ').', 422, 'rejected');
else if (!text) fail('EMPTY_AI_RESPONSE', 'AI không trả về nội dung (finishReason=' + (finishReason || 'unknown') + ').', 502, 'failed');
else {
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { ai = JSON.parse(cleaned); } catch (e) { ai = null; }
  if (!ai || typeof ai !== 'object' || Array.isArray(ai)) {
    ai = null;
    fail(finishReason === 'MAX_TOKENS' ? 'AI_TRUNCATED' : 'AI_BAD_JSON', 'Không đọc được kết quả AI trả về (finishReason=' + (finishReason || 'unknown') + ').', 502, 'failed');
  }
}

// ---------- chuẩn hóa từng loại giá trị ----------
const clean = (v, max) => { const t = s(v, max); return t && !/^(null|n\/a|none|không có)$/i.test(t) ? t : ''; };
const normEmail = (v) => { const t = clean(v, 320).toLowerCase().replace(/^mailto:/, '').split(/[\s,;]/)[0]; return t; };
const normPhone = (v) => {
  let t = clean(v, 60).split(/[,;\/]/)[0].replace(/[^\d+]/g, '');
  if (/^84\d{9,10}$/.test(t)) t = '+' + t;
  else if (/^0\d{9,10}$/.test(t)) t = '+84' + t.slice(1);
  const d = t.replace(/\D/g, '');
  return d.length >= 9 && d.length <= 15 ? t : '';
};
const normSite = (v) => { const t = clean(v, 200).toLowerCase().replace(/^https?:\/\//, '').replace(/\/+$/, ''); return /^[a-z0-9][a-z0-9.\-]*\.[a-z]{2,}(\/.*)?$/.test(t) ? t : ''; };
const isoDate = (v) => {
  const t = clean(v, 40); if (!t) return null;
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/), y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else { m = t.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/); if (!m) return null; d = +m[1]; mo = +m[2]; y = +m[3]; }
  if (mo < 1 || mo > 12 || d < 1 || d > 31 || y < 1900 || y > 2200) return null;
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCMonth() === mo - 1 ? dt.toISOString().slice(0, 10) : null;
};
// Chuẩn hóa tiền tệ: "VNĐ", "đồng", "vnd" => "VND" để các workflow sau (báo giá, gia hạn) so sánh được.
const normCur = (v) => { const c = clean(v, 20).toUpperCase().replace(/\./g, ''); if (!c) return null; if (/^(VND|VNĐ|ĐỒNG|Đ|VN ĐỒNG|VIỆT NAM ĐỒNG)$/.test(c)) return 'VND'; return c.slice(0, 10); };
const num = (v) => { if (v === null || v === undefined || v === '') return null; const n = Number(v); return Number.isFinite(n) && n >= 0 ? n : null; };

let docType = '', confidence = 0, language = '', rawText = '', businessCard = null, contract = null;
const warnings = [], reviewReasons = [];
let identity = '';

if (ai) {
  docType = s(ai.documentType, 30);
  confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));
  language = clean(ai.language, 20);
  rawText = s(ai.rawText, L.maxTextChars);

  if (docType === 'unreadable' || (docType !== 'business_card' && docType !== 'contract' && docType !== 'other')) {
    fail('UNREADABLE_FILE', 'Không đọc được chữ trong file (mờ, trống hoặc không phải tài liệu). Hãy chụp lại rõ hơn.', 422, 'rejected');
  } else if (docType === 'other') {
    fail('UNSUPPORTED_DOCUMENT', 'Tài liệu không phải danh thiếp hay hợp đồng. WF-10 hiện chỉ bóc tách hai loại này.', 422, 'rejected');
  } else if (rawText.length < 10) {
    fail('UNREADABLE_FILE', 'Không đọc được chữ trong file. Hãy chụp lại rõ hơn.', 422, 'rejected');
  }
}

if (errors.length === 0) {
  if (up.docType !== 'auto' && up.docType !== docType) reviewReasons.push('DOC_TYPE_DIFFERS_FROM_HINT');
  if (confidence < L.minConfidence) reviewReasons.push('LOW_CONFIDENCE');

  if (docType === 'business_card') {
    const b = ai.businessCard || {};
    const emailRaw = clean(b.email, 320);
    const email = normEmail(b.email);
    const emailOk = EMAIL_RE.test(email);
    const phoneRaw = clean(b.phone, 60);
    const phone = normPhone(b.phone);
    if (emailRaw && !emailOk) warnings.push('INVALID_EMAIL');
    if (phoneRaw && !phone) warnings.push('INVALID_PHONE');
    businessCard = {
      fullName: clean(b.fullName, 100), jobTitle: clean(b.jobTitle, 150), companyName: clean(b.companyName, 200),
      email: emailOk ? email : '', phone, phoneOther: clean(b.phoneOther, 120), website: normSite(b.website), address: clean(b.address, 300),
    };
    identity = businessCard.email ? 'email:' + businessCard.email : (businessCard.phone ? 'phone:' + businessCard.phone : '');
    if (!businessCard.fullName) reviewReasons.push('NO_NAME');
    if (!identity) reviewReasons.push('NO_CONTACT');
  } else if (docType === 'contract') {
    const k = ai.contract || {};
    const parties = (Array.isArray(k.parties) ? k.parties : []).slice(0, 10)
      .map((p) => ({ name: clean(p && p.name, 200), role: clean(p && p.role, 60), representative: clean(p && p.representative, 120) }))
      .filter((p) => p.name);
    contract = {
      title: clean(k.title, 300), contractNumber: clean(k.contractNumber, 100),
      signedDate: isoDate(k.signedDate), effectiveDate: isoDate(k.effectiveDate), expiryDate: isoDate(k.expiryDate),
      parties, totalValue: num(k.totalValue), currency: normCur(k.currency),
      paymentTerms: clean(k.paymentTerms, 1000), renewalTerms: clean(k.renewalTerms, 1000), summary: clean(k.summary, 1000),
    };
    if (!parties.length) reviewReasons.push('NO_PARTIES');
    if (!contract.signedDate && !contract.effectiveDate && !contract.expiryDate) reviewReasons.push('NO_DATES');
    const start = contract.effectiveDate || contract.signedDate;
    if (start && contract.expiryDate && contract.expiryDate < start) reviewReasons.push('EXPIRY_BEFORE_START');
  }
}

const ok = errors.length === 0;
const needsReview = ok && reviewReasons.length > 0;
let leadReason = 'OK';
if (docType !== 'business_card') leadReason = 'NOT_BUSINESS_CARD';
else if (!up.createLead) leadReason = 'CREATE_LEAD_DISABLED';
else if (needsReview) leadReason = 'NEEDS_REVIEW';
const leadCreate = ok && leadReason === 'OK';

return {
  json: {
    ok, httpCode, logStatus, errors,
    status: ok ? (needsReview ? 'needs_review' : 'extracted') : logStatus,
    docType, confidence, language, rawText, businessCard, contract, warnings, reviewReasons, needsReview,
    identity, leadPlan: { create: leadCreate, reason: leadReason }, provider,
  },
};

