  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

// WF-10 | Stage 8 - Transformation: dựng body POST /leads từ danh thiếp (gộp với lead cũ nếu đã có).
// Vì sao phải gộp: POST /leads là upsert, trường nào không gửi sẽ bị ghi đè thành NULL (xem tài liệu WF-07).
const p = $('11 Parse and Validate Result').first().json;
const v = $('03 Validate Upload').first().json;
const doc = $('13 Create Document Row').first().json;
const old = $('15 Load Existing Lead').first().json || {};
const known = !!old.id;
const bc = p.businessCard;

const pickStr = (nv, ov, max) => (nv ? nv : (ov ? String(ov).slice(0, max) : ''));
const oldMeta = (old.metadata && typeof old.metadata === 'object') ? old.metadata : {};

const body = {
  organizationId: v.organizationId,
  externalSource: 'omnichannel',               // cùng khóa với WF-07 để danh thiếp và form liên hệ của cùng một người gộp thành 1 lead
  externalId: p.identity.slice(0, 160),
  firstName: pickStr(bc.fullName, old.first_name, 100),
  lastName: pickStr('', old.last_name, 100),
  companyName: pickStr(bc.companyName, old.company_name, 200),
  email: pickStr(bc.email, old.email, 320),
  phone: pickStr(bc.phone, old.phone, 40),
  source: old.source ? String(old.source).slice(0, 80) : 'ocr:business-card',   // giữ nguồn chạm đầu tiên
  metadata: {
    ...oldMeta,
    ocr: {
      workflow: 'WF-10', documentId: doc.id, scannedAt: new Date().toISOString(), confidence: p.confidence,
      jobTitle: bc.jobTitle || null, website: bc.website || null, address: bc.address || null, phoneOther: bc.phoneOther || null,
      lastCorrelationId: v.correlationId,
    },
  },
};
for (const k of ['firstName', 'lastName', 'companyName', 'email', 'phone']) if (!body[k]) delete body[k];

return { json: { leadBody: body, knownLead: known, idempotencyKey: ('wf10:' + v.upload.fileHash).slice(0, 250) } };

